/* Бинарный поиск глифа по Unicode code point */
static inline const L8FontGlyph* luna8_get_glyph(uint32_t cp) {
    int l = 0, r = FONT_COUNT - 1;
    while (l <= r) {
        int m = l + (r - l) / 2;
        if (luna8_font[m].cp == cp) return &luna8_font[m];
        if (luna8_font[m].cp < cp) l = m + 1;
        else r = m - 1;
    }
    return NULL;
}
